export function createIndeterminateCheckbox(root) {
  const selectAll=root.querySelector('[data-select-all]');
  const children=[...root.querySelectorAll('[data-child-checkbox]')];
  const status=root.querySelector('[data-checkbox-status]');
  if(!(selectAll instanceof HTMLInputElement)||!children.length||!(status instanceof HTMLElement)) throw new Error('Indeterminate checkbox markup is incomplete.');
  const update=()=>{const count=children.filter(input=>input.checked).length;selectAll.checked=count===children.length;selectAll.indeterminate=count>0&&count<children.length;status.textContent=`${count} of ${children.length} channels selected.`;};
  const toggleAll=()=>{children.forEach(input=>{input.checked=selectAll.checked;});update();};
  selectAll.addEventListener('change',toggleAll);children.forEach(input=>input.addEventListener('change',update));update();
  return {destroy(){selectAll.removeEventListener('change',toggleAll);children.forEach(input=>input.removeEventListener('change',update));}};
}
document.querySelectorAll('[data-component="indeterminate-checkbox"]').forEach(createIndeterminateCheckbox);

