export function createCustomSelect(root) {
  const field = root.querySelector('[data-custom-select]');
  const trigger = field?.querySelector('[role="combobox"]');
  const listbox = field?.querySelector('[role="listbox"]');
  const valueInput = field?.querySelector('input[type="hidden"]');
  const valueLabel = trigger?.querySelector('[data-value-label]');
  const status = root.querySelector('[data-select-status]');
  if (!field || !trigger || !listbox || !valueInput || !valueLabel) throw new Error('Custom select markup is incomplete.');
  let typeahead = '';
  let typeaheadTimer;
  const options = () => [...listbox.querySelectorAll('[role="option"]')];
  const close = (restoreFocus = false) => {
    listbox.hidden = true;
    trigger.setAttribute('aria-expanded', 'false');
    if (restoreFocus) trigger.focus();
  };
  const open = (edge = 'selected') => {
    listbox.hidden = false;
    trigger.setAttribute('aria-expanded', 'true');
    const items = options();
    const selected = items.findIndex((option) => option.dataset.value === valueInput.value);
    const index = selected >= 0 ? selected : edge === 'last' ? items.length - 1 : 0;
    items[index]?.focus();
  };
  const choose = (option) => {
    if (!option) return;
    valueInput.value = option.dataset.value;
    valueLabel.textContent = option.dataset.label;
    trigger.dataset.empty = 'false';
    options().forEach((item) => item.setAttribute('aria-selected', String(item === option)));
    if (status) status.textContent = `Selected: ${option.dataset.label}.`;
    valueInput.dispatchEvent(new Event('input', { bubbles: true }));
    valueInput.dispatchEvent(new Event('change', { bubbles: true }));
    root.dispatchEvent(new CustomEvent('select:change', { detail: { value: valueInput.value } }));
    close(true);
  };
  const onTriggerClick = () => listbox.hidden ? open() : close();
  const onTriggerKeydown = (event) => {
    if (['ArrowDown', 'ArrowUp', 'Enter', ' '].includes(event.key)) {
      event.preventDefault();
      open(event.key === 'ArrowUp' ? 'last' : 'selected');
    }
  };
  const onListboxClick = (event) => {
    const option = event.target.closest('[role="option"]');
    if (option && listbox.contains(option)) choose(option);
  };
  const onListboxKeydown = (event) => {
    const items = options();
    let index = items.indexOf(document.activeElement);
    if (event.key === 'Escape') { event.preventDefault(); close(true); return; }
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp' || event.key === 'Home' || event.key === 'End') {
      event.preventDefault();
      index = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : Math.max(0, Math.min(items.length - 1, index + (event.key === 'ArrowDown' ? 1 : -1)));
      items[index]?.focus();
      items[index]?.scrollIntoView({ block: 'nearest' });
      return;
    }
    if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); choose(items[index]); return; }
    if (event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey) {
      typeahead += event.key.toLocaleLowerCase();
      window.clearTimeout(typeaheadTimer);
      typeaheadTimer = window.setTimeout(() => { typeahead = ''; }, 650);
      const match = items.findIndex((item) => item.dataset.label.toLocaleLowerCase().startsWith(typeahead));
      if (match >= 0) items[match].focus();
    }
  };
  const onDocumentPointer = (event) => { if (!field.contains(event.target)) close(); };
  const onFocusOut = () => window.setTimeout(() => { if (!field.contains(document.activeElement)) close(); });
  trigger.addEventListener('click', onTriggerClick);
  trigger.addEventListener('keydown', onTriggerKeydown);
  listbox.addEventListener('click', onListboxClick);
  listbox.addEventListener('keydown', onListboxKeydown);
  field.addEventListener('focusout', onFocusOut);
  document.addEventListener('pointerdown', onDocumentPointer);
  return { destroy() {
    window.clearTimeout(typeaheadTimer);
    trigger.removeEventListener('click', onTriggerClick);
    trigger.removeEventListener('keydown', onTriggerKeydown);
    listbox.removeEventListener('click', onListboxClick);
    listbox.removeEventListener('keydown', onListboxKeydown);
    field.removeEventListener('focusout', onFocusOut);
    document.removeEventListener('pointerdown', onDocumentPointer);
  } };
}
document.querySelectorAll('[data-component="select"], [data-component="grouped-select"]').forEach(createCustomSelect);

