export function createCascadeSelect(root) {
  const trigger = root.querySelector('[role="combobox"]');
  const tree = root.querySelector('[role="tree"]');
  const hidden = root.querySelector('input[type="hidden"]');
  const valueLabel = trigger?.querySelector('[data-value-label]');
  const status = root.querySelector('[data-cascade-status]');
  if (!trigger || !tree || !hidden || !valueLabel || !status) throw new Error('Cascade select markup is incomplete.');
  const items = () => [...tree.querySelectorAll('[role="treeitem"]')];
  const groupOf = (item) => item.parentElement.querySelector(':scope > [role="group"]');
  const isBranch = (item) => Boolean(groupOf(item));
  const visibleItems = () => items().filter((item) => !item.closest('[hidden]'));
  const close = (restoreFocus = false) => {
    tree.hidden = true;
    trigger.setAttribute('aria-expanded', 'false');
    if (restoreFocus) trigger.focus();
  };
  const focusItem = (item) => {
    if (!item) return;
    item.focus();
    item.scrollIntoView({block:'nearest'});
  };
  const expand = (item, open = true, moveInto = false) => {
    const group = groupOf(item);
    if (!group) return;
    item.setAttribute('aria-expanded', String(open));
    group.hidden = !open;
    if (open && moveInto) focusItem(group.querySelector('[role="treeitem"]'));
  };
  const open = (last = false) => {
    tree.hidden = false;
    trigger.setAttribute('aria-expanded', 'true');
    const selected = items().find((item) => item.dataset.value === hidden.value);
    if (selected) {
      const ancestors = [];
      let parent = selected.parentElement.closest('[role="treeitem"]');
      while (parent) { ancestors.unshift(parent); parent = parent.parentElement.closest('[role="treeitem"]'); }
      ancestors.forEach((ancestor) => expand(ancestor, true));
      focusItem(selected);
    } else {
      const roots = tree.querySelectorAll(':scope > [role="group"] > [role="none"] > [role="treeitem"]');
      focusItem(last ? roots[roots.length - 1] : roots[0]);
    }
  };
  const choose = (item) => {
    if (!item?.dataset.value) return;
    hidden.value = item.dataset.value;
    const path = [];
    let current = item;
    while (current && current.matches('[role="treeitem"]')) {
      path.unshift(current.dataset.label);
      current = current.parentElement.closest('[role="treeitem"]');
    }
    valueLabel.textContent = path.join(' / ');
    trigger.dataset.empty = 'false';
    items().forEach((node) => {
      if (node.hasAttribute('aria-selected')) node.setAttribute('aria-selected', String(node === item));
    });
    status.textContent = `Selected: ${path.join(' / ')}.`;
    hidden.dispatchEvent(new Event('input', {bubbles:true}));
    hidden.dispatchEvent(new Event('change', {bubbles:true}));
    root.dispatchEvent(new CustomEvent('select:change', {detail:{value:hidden.value}}));
    close(true);
  };
  const onTriggerClick = () => tree.hidden ? open() : close();
  const onTriggerKey = (event) => {
    if (['ArrowDown','ArrowUp','Enter',' '].includes(event.key)) { event.preventDefault(); open(event.key === 'ArrowUp'); }
  };
  const onTreeClick = (event) => {
    const item = event.target.closest('[role="treeitem"]');
    if (!item || !tree.contains(item)) return;
    if (isBranch(item)) expand(item, item.getAttribute('aria-expanded') !== 'true');
    else choose(item);
  };
  const onTreeKey = (event) => {
    const item = event.target.closest('[role="treeitem"]');
    const visible = visibleItems();
    let index = visible.indexOf(item);
    if (event.key === 'Escape') { event.preventDefault(); close(true); return; }
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp' || event.key === 'Home' || event.key === 'End') {
      event.preventDefault();
      index = event.key === 'Home' ? 0 : event.key === 'End' ? visible.length - 1 : Math.max(0, Math.min(visible.length - 1, index + (event.key === 'ArrowDown' ? 1 : -1)));
      focusItem(visible[index]);
    } else if (event.key === 'ArrowRight' && item && isBranch(item)) {
      event.preventDefault();
      if (item.getAttribute('aria-expanded') !== 'true') expand(item, true, true);
      else focusItem(groupOf(item).querySelector('[role="treeitem"]'));
    } else if (event.key === 'ArrowLeft' && item) {
      event.preventDefault();
      if (isBranch(item) && item.getAttribute('aria-expanded') === 'true') expand(item, false);
      else focusItem(item.parentElement.closest('[role="treeitem"]'));
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      if (item && isBranch(item)) expand(item, item.getAttribute('aria-expanded') !== 'true', item.getAttribute('aria-expanded') !== 'true');
      else choose(item);
    }
  };
  const onOutsidePointer = (event) => { if (!root.contains(event.target)) close(); };
  const onFocusOut = () => window.setTimeout(() => { if (!root.contains(document.activeElement)) close(); });
  trigger.addEventListener('click', onTriggerClick);
  trigger.addEventListener('keydown', onTriggerKey);
  tree.addEventListener('click', onTreeClick);
  tree.addEventListener('keydown', onTreeKey);
  root.addEventListener('focusout', onFocusOut);
  document.addEventListener('pointerdown', onOutsidePointer);
  return { destroy() {
    trigger.removeEventListener('click', onTriggerClick);
    trigger.removeEventListener('keydown', onTriggerKey);
    tree.removeEventListener('click', onTreeClick);
    tree.removeEventListener('keydown', onTreeKey);
    root.removeEventListener('focusout', onFocusOut);
    document.removeEventListener('pointerdown', onOutsidePointer);
  } };
}
document.querySelectorAll('[data-component="cascade-select"]').forEach(createCascadeSelect);

